mapper.select:
SELECT
    a.attachment_id AS attachmentId,
    a.business_type AS businessType,
    a.business_id AS businessId,
    CASE
        WHEN a.business_type = 'TENDER' THEN t.tender_name
        WHEN a.business_type = 'BID' THEN b.bid_name
        ELSE '未知业务'
    END AS businessName,
    a.file_type AS fileType,
    a.file_category AS fileCategory,
    a.file_name AS fileName,
    a.file_size AS fileSize,
    a.file_format AS fileFormat,
    a.version_no AS versionNo,
    a.is_latest AS isLatest,
    u.user_name AS uploadUserName,
    a.upload_time AS uploadTime,
    a.download_count AS downloadCount,
    a.file_status AS fileStatus,
    a.security_level AS securityLevel,
    cu.user_name AS createdByName,
    a.created_time AS createdTime
FROM exp_attachment a
LEFT JOIN exp_tender t ON a.business_type = 'TENDER' AND a.business_id = t.tender_id
LEFT JOIN exp_bid b ON a.business_type = 'BID' AND a.business_id = b.bid_id
LEFT JOIN exp_user u ON a.upload_user_id = u.user_id
LEFT JOIN exp_user cu ON a.created_by = cu.user_id


        AND a.business_type = #{req.businessType}


        AND a.business_id = #{req.businessId}


        AND a.file_type = #{req.fileType}


        AND a.file_category = #{req.fileCategory}


        AND a.file_name LIKE CONCAT('%', #{req.fileName}, '%')


        AND a.file_format = #{req.fileFormat}


        AND a.upload_user_id = #{req.uploadUserId}


        AND a.security_level = #{req.securityLevel}


        AND a.file_status = #{req.fileStatus}


        AND a.upload_time >= #{req.uploadTimeStart}


        AND a.upload_time <= #{req.uploadTimeEnd}


        AND a.created_by = #{req.createdBy}


        AND a.created_time >= #{req.createdTimeStart}


        AND a.created_time <= #{req.createdTimeEnd}


ORDER BY a.created_time DESC

SELECT COUNT(1)
FROM exp_attachment
WHERE file_name = #{fileName}
AND file_md5 = #{fileMd5}
AND business_type = #{businessType}
AND business_id = #{businessId}
AND file_status = '正常'

